export function resolveLanguage(query, stored) {
  return [query, stored].find(value => value === 'fa' || value === 'en') || 'fa';
}

export function translate(language, key, values = {}) {
  const text = messages[language]?.[key] ?? messages.fa[key];
  if (text === undefined) throw new Error(`Missing translation: ${key}`);
  return text.replace(/\{(\w+)\}/g, (_, name) => String(values[name] ?? `{${name}}`));
}

export function formatNumber(value, language) {
  return new Intl.NumberFormat(language === 'fa' ? 'fa-IR' : 'en-US', {maximumFractionDigits: 1}).format(value);
}
